-        <div class="calendar-event-create-edit-dialog-rows"></div>
+        <div class="calendar-event-create-edit-dialog-rows">
+          <calendar-dialog-toggleable-row
+            class="calendar-event-category-row"
+            checked="checked"
+          >
+            <!--
+              The shared row owns expansion. Category actions are added in Bug
+              2084433.
+            -->
+            <img slot="icon" class="icon-category" src="" alt="" />
+            <span slot="label" data-l10n-id="calendar-event-categories"></span>
+            <div slot="content" class="calendar-event-category-content">
+              <button
+                class="button button-flat icon-button calendar-event-add-category"
+                type="button"
+                data-l10n-id="calendar-event-add-category"
+              ></button>
+              <!--
+                Keep the choices separate from selected chips. Neither list
+                loads data here.
+              -->
+              <ul
+                class="calendar-event-category-choices"
+                data-l10n-id="calendar-event-category-choices"
+                hidden="hidden"
+              ></ul>
+              <div class="calendar-event-category-summary">
+                <ul
+                  class="calendar-event-category-list"
+                  data-l10n-id="calendar-event-selected-categories"
+                ></ul>
+                <!--
+                  The controller supplies the count and opens the remaining
+                  list later.
+                -->
+                <button
+                  class="button button-flat calendar-event-more-categories"
+                  type="button"
+                  data-l10n-id="calendar-event-more-categories"
+                  data-l10n-args="{&quot;count&quot;:0}"
+                  hidden="hidden"
+                ></button>
+              </div>
+              <!--
+                This bounded area scrolls inside the dialog instead of resizing
+                it.
+              -->
+              <ul
+                class="calendar-event-category-overflow"
+                data-l10n-id="calendar-event-remaining-categories"
+                tabindex="0"
+                hidden="hidden"
+              ></ul>
+              <!--
+                Clone one chip per selection. Test samples never enter event
+                draft state.
+              -->
+              <template class="calendar-event-category-chip-template">
+                <li class="calendar-event-category-chip">
+                  <span class="calendar-event-category-label"></span>
+                  <button
+                    class="button button-flat icon-button icon-only
+                      calendar-event-remove-category"
+                    type="button"
+                    data-l10n-id="calendar-event-remove-category"
+                    data-l10n-args="{&quot;category&quot;:&quot;&quot;}"
+                  ></button>
+                </li>
+              </template>
+            </div>
+          </calendar-dialog-toggleable-row>
+        </div>
       </section>
     </div>
   </main>
