diff --git a/mail/components/calendar/test/browser/browser_calendarEventCategoryRow.js b/mail/components/calendar/test/browser/browser_calendarEventCategoryRow.js
new file mode 100644
index 00000000000..8ce798519a7
--- /dev/null
+++ b/mail/components/calendar/test/browser/browser_calendarEventCategoryRow.js
@@ -0,0 +1,566 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+"use strict";
+
+const {
+  assertNoAxeMutationObserverViolations,
+  startAxeMutationObserverInWindow,
+} = ChromeUtils.importESModule(
+  "resource://testing-common/mail/AxeHelpers.sys.mjs"
+);
+
+let browser;
+let doc;
+let dialog;
+let row;
+let axeWatcher;
+
+add_setup(async function () {
+  const tabmail = document.getElementById("tabmail");
+  let tab = null;
+
+  // Register cleanup before loading the fixture so a failed setup closes its tab.
+  registerCleanupFunction(async () => {
+    // Finish axe before closing the document that owns its observed nodes.
+    // Keep cleanup running even if the checker itself cannot finish.
+    let axeError;
+    const report = await axeWatcher?.finish({ assert: false }).catch(error => {
+      axeError = error;
+    });
+
+    dialog?.close();
+    if (tab) {
+      tabmail.closeTab(tab);
+    }
+
+    if (axeError) {
+      throw axeError;
+    }
+
+    if (!report) {
+      return;
+    }
+
+    assertNoAxeMutationObserverViolations(
+      report,
+      "Category row states should pass axe checks"
+    );
+
+    if (report.skipped) {
+      info(`Category axe checks skipped: ${report.skippedReason}`);
+
+      return;
+    }
+
+    Assert.greater(report.runCount, 0, "Axe should inspect category states");
+  });
+
+  await SpecialPowers.pushPrefEnv({ set: [["general.smoothScroll", false]] });
+  tab = tabmail.openTab("contentTab", {
+    url: "chrome://mochitests/content/browser/comm/mail/components/calendar/test/browser/files/calendarEventCreateEditDialog.xhtml",
+  });
+  browser = tab.browser;
+
+  await BrowserTestUtils.browserLoaded(browser, undefined, url =>
+    url.endsWith("calendarEventCreateEditDialog.xhtml")
+  );
+  await SimpleTest.promiseFocus(browser);
+
+  doc = browser.contentWindow.document;
+  dialog = doc.querySelector('[is="calendar-event-create-edit-dialog"]');
+  row = dialog.querySelector(".calendar-event-category-row");
+  // Give the shell its intended panel height without changing production sizing.
+  dialog.style.inlineSize = "480px";
+  dialog.style.blockSize = "480px";
+
+  Assert.ok(await dialog.show(), "The category fixture dialog should open");
+  await doc.l10n.translateFragment(dialog);
+
+  axeWatcher = await startAxeMutationObserverInWindow(browser.contentWindow, {
+    autoFinish: false,
+    container: dialog,
+    context: dialog,
+    message: "Category row states should pass axe checks",
+  });
+});
+
+/**
+ * Returns a chip cloned from production-shaped markup with fixed test values.
+ *
+ * @param {string} name - The sample category label.
+ * @returns {HTMLLIElement} The detached chip with localization attributes.
+ */
+function makeChip(name) {
+  const template = row.querySelector(".calendar-event-category-chip-template");
+  const chip = template.content.firstElementChild.cloneNode(true);
+  const label = chip.querySelector(".calendar-event-category-label");
+  const remove = chip.querySelector(".calendar-event-remove-category");
+
+  label.textContent = name;
+  doc.l10n.setAttributes(remove, "calendar-event-remove-category", {
+    category: name,
+  });
+
+  return chip;
+}
+
+/**
+ * Shows fixed category samples without loading preferences or changing a draft.
+ *
+ * @param {string[]} names - Chips to show in the summary.
+ * @param {string[]} [remaining=[]] - Chips to show in the scrollable area.
+ * @returns {Promise<void>} Resolves after the samples are translated and checked.
+ */
+async function showSamples(names, remaining = []) {
+  const list = row.querySelector(".calendar-event-category-list");
+  const overflow = row.querySelector(".calendar-event-category-overflow");
+  const more = row.querySelector(".calendar-event-more-categories");
+
+  // The follow-up controller owns chip capacity. These tests choose samples
+  // directly so markup tests do not implement category selection or measurement.
+  const selectedChips = doc.createDocumentFragment();
+  const remainingChips = doc.createDocumentFragment();
+
+  selectedChips.append(...names.map(makeChip));
+  remainingChips.append(...remaining.map(makeChip));
+
+  // Translate before insertion so neither speech users nor axe encounter a
+  // temporary icon-only button without its category-specific name.
+  await doc.l10n.translateFragment(selectedChips);
+  await doc.l10n.translateFragment(remainingChips);
+
+  row.setAttribute("checked", "checked");
+  list.replaceChildren(selectedChips);
+  overflow.replaceChildren(remainingChips);
+  overflow.scrollTop = 0;
+  overflow.hidden = !remaining.length;
+  more.hidden = !remaining.length;
+  doc.l10n.setAttributes(more, "calendar-event-more-categories", {
+    count: remaining.length,
+  });
+
+  await doc.l10n.translateFragment(row);
+  await axeWatcher.flush();
+}
+
+add_task(async function test_emptyMarkupAndLabels() {
+  const add = row.querySelector(".calendar-event-add-category");
+  const choices = row.querySelector(".calendar-event-category-choices");
+  const selected = row.querySelector(".calendar-event-category-list");
+
+  const productionRow = document
+    .getElementById("calendarEventCreateEditDialogTemplate")
+    .content.querySelector(".calendar-event-category-row");
+  const fixtureRow = doc
+    .getElementById("calendarEventCreateEditDialogTemplate")
+    .content.querySelector(".calendar-event-category-row");
+
+  Assert.ok(
+    productionRow,
+    "The production dialog should include category markup"
+  );
+  Assert.ok(fixtureRow, "The fixture template should include category markup");
+  Assert.equal(
+    fixtureRow.outerHTML.replace(/\s+/g, " "),
+    productionRow.outerHTML.replace(/\s+/g, " "),
+    "The fixture should match the production category markup"
+  );
+  Assert.equal(
+    row.localName,
+    "calendar-dialog-toggleable-row",
+    "Categories should use the shared create/edit row"
+  );
+  Assert.equal(add.type, "button", "Add category should be a native button");
+  Assert.equal(
+    doc.l10n.getAttributes(add).id,
+    "calendar-event-add-category",
+    "Add category should use its translated label"
+  );
+  Assert.equal(
+    selected.childElementCount,
+    0,
+    "The production-shaped row should start without sample categories"
+  );
+  Assert.ok(BrowserTestUtils.isHidden(choices), "Choices should start hidden");
+  Assert.ok(
+    BrowserTestUtils.isHidden(
+      row.querySelector(".calendar-event-more-categories")
+    ),
+    "The overflow control should start hidden"
+  );
+  Assert.ok(
+    BrowserTestUtils.isHidden(
+      row.querySelector(".calendar-event-category-overflow")
+    ),
+    "Remaining categories should start hidden"
+  );
+
+  await axeWatcher.flush();
+});
+
+add_task(async function test_sharedRowExpansion() {
+  const checkbox = row.shadowRoot.querySelector(".toggle-checkbox");
+  const add = row.querySelector(".calendar-event-add-category");
+  const initialDraft = dialog.draft;
+
+  Assert.equal(
+    doc.l10n.getAttributes(row.querySelector('[slot="label"]')).id,
+    "calendar-event-categories",
+    "The shared checkbox should receive the translated Categories label"
+  );
+
+  checkbox.focus();
+  EventUtils.synthesizeKey(" ", {}, browser.contentWindow);
+
+  Assert.ok(
+    BrowserTestUtils.isHidden(
+      row.shadowRoot.querySelector('slot[name="content"]')
+    ),
+    "Space should collapse category content"
+  );
+  Assert.equal(
+    add.getClientRects().length,
+    0,
+    "The collapsed row should not render Add category"
+  );
+  Assert.equal(
+    checkbox.getAttribute("aria-expanded"),
+    "false",
+    "The checkbox should announce collapsed content"
+  );
+
+  EventUtils.synthesizeKey(" ", {}, browser.contentWindow);
+
+  Assert.ok(
+    BrowserTestUtils.isVisible(add),
+    "Space should expand category content"
+  );
+  Assert.equal(
+    checkbox.getAttribute("aria-expanded"),
+    "true",
+    "The checkbox should announce expanded content"
+  );
+  Assert.deepEqual(
+    dialog.draft,
+    initialDraft,
+    "Row expansion should not change the draft"
+  );
+
+  await axeWatcher.flush();
+});
+
+add_task(async function test_chipsAndKeyboardControls() {
+  await showSamples(["Work", "Personal"]);
+
+  const add = row.querySelector(".calendar-event-add-category");
+  const remove = row.querySelector(".calendar-event-remove-category");
+  const checkbox = row.shadowRoot.querySelector(".toggle-checkbox");
+  const initialDraft = dialog.draft;
+
+  checkbox.focus();
+  EventUtils.synthesizeKey("KEY_Tab", {}, browser.contentWindow);
+  Assert.equal(doc.activeElement, add, "Tab should reach Add category");
+  EventUtils.synthesizeKey("KEY_Tab", {}, browser.contentWindow);
+  Assert.equal(
+    doc.activeElement,
+    remove,
+    "Tab should reach the chip remove button"
+  );
+  Assert.ok(
+    remove.matches(":focus-visible"),
+    "Keyboard focus should be visible"
+  );
+  Assert.notEqual(
+    browser.contentWindow.getComputedStyle(remove).outlineStyle,
+    "none",
+    "The focused remove button should have an outline"
+  );
+
+  const clicked = BrowserTestUtils.waitForEvent(remove, "click");
+  EventUtils.synthesizeKey("KEY_Enter", {}, browser.contentWindow);
+  await clicked;
+
+  Assert.deepEqual(
+    dialog.draft,
+    initialDraft,
+    "Static controls should not patch the draft"
+  );
+  Assert.equal(
+    row.querySelector(".calendar-event-category-list").childElementCount,
+    2,
+    "Static remove markup should leave selection actions to the follow-up bug"
+  );
+
+  // Inspect the native accessibility tree, not only the ARIA source attributes.
+  const service = Cc["@mozilla.org/accessibilityService;1"].getService(
+    Ci.nsIAccessibilityService
+  );
+  let accessible;
+
+  await TestUtils.waitForCondition(
+    () =>
+      (accessible = service.getAccessibleFor(remove))?.name ==
+      "Remove category Work",
+    "The remove button should expose its category name to screen readers"
+  );
+  Assert.equal(
+    accessible.role,
+    Ci.nsIAccessibleRole.ROLE_PUSHBUTTON,
+    "The remove control should expose a native button role"
+  );
+  // Row expansion can finish before the native accessibility tree updates.
+  // Wait for the names that screen readers receive, not just DOM translation.
+  await TestUtils.waitForCondition(
+    () => service.getAccessibleFor(add)?.name == "Add category",
+    "The Add category name should reach the accessibility tree"
+  );
+  Assert.equal(
+    service.getAccessibleFor(add).name,
+    "Add category",
+    "Screen readers should receive the Add category name"
+  );
+  const selectedList = row.querySelector(".calendar-event-category-list");
+
+  await TestUtils.waitForCondition(
+    () => service.getAccessibleFor(selectedList)?.name == "Selected categories",
+    "The selected-list name should reach the accessibility tree"
+  );
+  Assert.equal(
+    service.getAccessibleFor(selectedList).name,
+    "Selected categories",
+    "Screen readers should receive the selected-list name"
+  );
+
+  await axeWatcher.flush();
+});
+
+add_task(async function test_overflowLabels() {
+  for (const remaining of [["Work"], ["Work", "Personal"]]) {
+    await showSamples(["Travel"], remaining);
+
+    const more = row.querySelector(".calendar-event-more-categories");
+    const count = remaining.length;
+    const expectedName = count == 1 ? "+1 more category" : "+2 more categories";
+
+    Assert.equal(
+      more.textContent,
+      `+${count} more`,
+      "The overflow label should show the sample count"
+    );
+    Assert.equal(
+      more.ariaLabel,
+      expectedName,
+      "The overflow name should include its visible label and correct plural"
+    );
+  }
+
+  await showSamples([]);
+});
+
+add_task(async function test_longLabelsAndOverflowStayInsideDialog() {
+  const longName = "A very long category label ".repeat(20);
+  // Two and three are sample counts, not an implementation of responsive capacity.
+  for (const count of [2, 3]) {
+    await showSamples(Array(count).fill(longName));
+
+    const list = row.querySelector(".calendar-event-category-list");
+    const listRect = list.getBoundingClientRect();
+    for (const chip of list.children) {
+      const label = chip.querySelector(".calendar-event-category-label");
+      const remove = chip.querySelector("button");
+      const style = browser.contentWindow.getComputedStyle(label);
+
+      Assert.equal(
+        style.whiteSpace,
+        "nowrap",
+        "Chip text should stay on one line"
+      );
+      Assert.equal(
+        style.textOverflow,
+        "ellipsis",
+        "Long labels should end with an ellipsis"
+      );
+      Assert.greater(
+        label.scrollWidth,
+        label.clientWidth,
+        "The long label should be clipped"
+      );
+      Assert.lessOrEqual(
+        remove.getBoundingClientRect().right,
+        listRect.right,
+        "The remove button should stay inside the summary"
+      );
+    }
+  }
+
+  await showSamples(["Work", "Personal", longName]);
+  for (const chip of row.querySelector(".calendar-event-category-list")
+    .children) {
+    const label = chip.querySelector(".calendar-event-category-label");
+    if (label.textContent == longName) {
+      continue;
+    }
+
+    Assert.equal(
+      label.scrollWidth,
+      label.clientWidth,
+      "Short labels should remain readable beside a long category"
+    );
+  }
+
+  const before = dialog.getBoundingClientRect();
+  const remaining = Array.from(
+    { length: 20 },
+    (_, index) => `Category ${index}`
+  );
+  await showSamples([longName, "Work", "Personal"], remaining);
+
+  const after = dialog.getBoundingClientRect();
+  const overflow = row.querySelector(".calendar-event-category-overflow");
+  const body = dialog.querySelector(".calendar-event-create-edit-dialog-body");
+  const overflowRect = overflow.getBoundingClientRect();
+  const bodyRect = body.getBoundingClientRect();
+
+  Assert.deepEqual(
+    [after.x, after.y, after.width, after.height],
+    [before.x, before.y, before.width, before.height],
+    "Showing remaining categories should preserve dialog size and position"
+  );
+  Assert.greater(
+    overflow.scrollHeight,
+    overflow.clientHeight,
+    "Remaining categories should scroll"
+  );
+  Assert.greaterOrEqual(
+    overflowRect.top,
+    bodyRect.top,
+    "Overflow should stay below the body top"
+  );
+  Assert.lessOrEqual(
+    overflowRect.bottom,
+    bodyRect.bottom,
+    "Overflow should stay above the body bottom"
+  );
+  Assert.greaterOrEqual(
+    overflowRect.left,
+    bodyRect.left,
+    "Overflow should stay inside the body start"
+  );
+  Assert.lessOrEqual(
+    overflowRect.right,
+    bodyRect.right,
+    "Overflow should stay inside the body end"
+  );
+
+  overflow.focus();
+  EventUtils.synthesizeKey("KEY_End", {}, browser.contentWindow);
+  await TestUtils.waitForCondition(
+    () => overflow.scrollTop > 0,
+    "Keyboard input should scroll the remaining categories"
+  );
+  Assert.equal(
+    doc.activeElement,
+    overflow,
+    "The scroll area should retain keyboard focus"
+  );
+  Assert.equal(
+    doc.l10n.getAttributes(row.querySelector(".calendar-event-more-categories"))
+      .args.count,
+    20,
+    "The sample overflow control should receive the translated count"
+  );
+
+  await axeWatcher.flush();
+});
+
+add_task(async function test_themesDensityDirectionAndForcedColors() {
+  await showSamples(["Work", "Personal", "Long category name ".repeat(20)]);
+
+  const chip = row.querySelector(".calendar-event-category-chip");
+  // These fixed colors exercise the style hooks without reading real categories.
+  chip.style.setProperty("--item-color", "rgb(0, 80, 120)");
+  chip.style.setProperty("--item-text-color", "rgb(255, 255, 255)");
+
+  for (const dark of [0, 1]) {
+    // Apply each theme while closed, then check the newly opened dialog.
+    // This avoids measuring unrelated button color transitions between themes.
+    dialog.close();
+    await SpecialPowers.pushPrefEnv({
+      set: [["ui.systemUsesDarkTheme", dark]],
+    });
+    await TestUtils.waitForCondition(
+      () =>
+        browser.contentWindow.matchMedia("(prefers-color-scheme: dark)")
+          .matches == !!dark,
+      "The requested color scheme should reach the category row"
+    );
+    Assert.ok(await dialog.show(), "The themed category dialog should open");
+
+    for (const density of ["compact", "normal", "touch"]) {
+      doc.documentElement.setAttribute("uidensity", density);
+      for (const direction of ["ltr", "rtl"]) {
+        doc.documentElement.dir = direction;
+        const style = browser.contentWindow.getComputedStyle(chip);
+        const list = row.querySelector(".calendar-event-category-list");
+
+        Assert.equal(
+          style.backgroundColor,
+          "rgb(0, 80, 120)",
+          "Chips should use the supplied background color"
+        );
+        Assert.equal(
+          style.color,
+          "rgb(255, 255, 255)",
+          "Chips should use the supplied text color"
+        );
+        Assert.lessOrEqual(
+          list.scrollWidth,
+          list.clientWidth,
+          "Chips should fit the summary in each theme, density, and direction"
+        );
+        await axeWatcher.flush();
+      }
+    }
+
+    dialog.close();
+    await SpecialPowers.popPrefEnv();
+  }
+
+  doc.documentElement.removeAttribute("uidensity");
+  doc.documentElement.removeAttribute("dir");
+  dialog.close();
+  await SpecialPowers.pushPrefEnv({
+    set: [["browser.display.document_color_use", 2]],
+  });
+  await TestUtils.waitForCondition(
+    () => browser.contentWindow.matchMedia("(forced-colors: active)").matches,
